package main

import "fmt"

// Notifier is a one-method interface (a behavioral contract).
type Notifier interface {
	Notify(msg string) string
}

type Email struct{ addr string }

// Email satisfies Notifier just by having this method — no declaration needed.
func (e Email) Notify(msg string) string {
	return fmt.Sprintf("email to %s: %s", e.addr, msg)
}

type SMS struct{ phone string }

func (s SMS) Notify(msg string) string {
	return fmt.Sprintf("sms to %s: %s", s.phone, msg)
}

// send accepts the interface, so it works with any Notifier (polymorphism).
func send(n Notifier, msg string) {
	fmt.Println(n.Notify(msg))
}

func main() {
	notifiers := []Notifier{Email{"a@x.com"}, SMS{"555-0100"}}
	for _, n := range notifiers {
		send(n, "deploy done") // dynamic dispatch picks the right Notify
	}
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

// describe accepts the empty interface, so any value can be passed.
func describe(v any) string {
	switch x := v.(type) { // type switch unboxes the dynamic type
	case int:
		return fmt.Sprintf("int=%d", x)
	case string:
		return fmt.Sprintf("string=%q", x)
	case fmt.Stringer:
		return "stringer=" + x.String()
	case nil:
		return "nil"
	default:
		return fmt.Sprintf("other %T", x)
	}
}

// report accepts io.Writer, so it works with files, buffers, network conns, etc.
func report(w io.Writer, label string) {
	fmt.Fprintf(w, "[%s] ok\n", label)
}

func main() {
	fmt.Println(describe(42))
	fmt.Println(describe("hi"))
	fmt.Println(describe(3.14))

	var sb strings.Builder
	report(&sb, "buffer") // *strings.Builder satisfies io.Writer
	report(os.Stdout, "stdout") // *os.File satisfies io.Writer
	fmt.Print(sb.String())
}

package main

import "fmt"

type MyError struct{ Msg string }

func (e *MyError) Error() string { return e.Msg }

// BUG: returns a typed nil (*MyError)(nil) as an error interface.
func doWorkBad() error {
	var e *MyError = nil // nil pointer of concrete type *MyError
	return e             // wrapped in error interface => type word set!
}

// CORRECT: return the untyped nil interface directly.
func doWorkGood() error {
	return nil
}

func main() {
	err := doWorkBad()
	// err's data word is nil, but its type word is *MyError, so err != nil.
	fmt.Println("bad  err == nil?", err == nil)
	fmt.Printf("bad  value: (%T, %v)\n", err, err)

	err = doWorkGood()
	fmt.Println("good err == nil?", err == nil)
}
